};

/********************************************** 
 * 함수명   : sri_search
 * 설명       : SRI 채권 신청 목록을 조회함
 ***********************************************/
scwin.sri_search = function() {
    //grd_List.ColumnProp("CHK", "headcheck") = false;
    //dts_List.ClearData(); 

    var param = '';
    var dsNm = 'BNSSRI_APPL_LIST';
    var qryId = 'lds.stf.bnssri.select.list';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : fn_formCheck
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheck = function() {
    if (scwin.p_SUPLY_YY == "N") {
        // 신규 접수 건
        if (!window.confirm("[" + txb_ISU_NM.getValue() + "]의 ESG채권 신청을 접수하시겠습니까? ")) {
            return false;
        } else {
            return 1;
        }
    } else {
        //조달자금보고 최종이면서 미사용잔액 '0'인치 체크후 안내메세지
        if (txb_SUPLY_FND_USE_RPT_RND_TP_CD.getValue() == '3' && edt_UNUSED_AMT.getValue() != '0') {
            $c.win.alert("미사용잔액이 있습니다.");
        }
        if (window.confirm("[" + txb_ISU_NM.getValue() + "]의 " + txb_SUPLY_FND_USE_RPT_YY.getValue() + "년도 사후보고를 접수하시겠습니까? ")) {
            return 1;
        } else {
            return false;
        }
    }
};




/********************************************** 
 * 함수명   : fn_formCheckComplt
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheckComplt = function() {
    if (scwin.p_SUPLY_YY == "N") {
        // 신규 접수 건
        if (!window.confirm("[" + txb_ISU_NM.getValue() + "]의 ESG채권등록 신청을 처리완료 하시겠습니까? ")) {
            return false;
        } else {
            return 1;
        }
    } else {
        if (window.confirm("[" + txb_ISU_NM.getValue() + "]의 " + txb_SUPLY_FND_USE_RPT_YY.getValue() + "년도 사후보고를 처리완료 하시겠습니까? ")) {
            return 1;
        } else {
            return false;
        }
    }
};




/********************************************** 
 * 함수명   : fn_formCheckTeamleadr
 * 설명       : 폼을 체크한다.
 ***********************************************/
scwin.fn_formCheckTeamleadr = function() {
    //담당자는 팀장확인 안됨.
    if (js_jobtitl == '03') {
        $c.win.alert('팀장권한만 가능합니다.');
        return false;
    } else {
        if (scwin.p_SUPLY_YY == "N") {
            // 신규 접수 건
            if (!window.confirm("[" + txb_ISU_NM.getValue() + "]의 ESG채권등록 신청을 팀장확인 하시겠습니까? ")) {
                return false;
            } else {
                return 1;
            }
        } else {
            if (window.confirm("[" + txb_ISU_NM.getValue() + "]의 " + txb_SUPLY_FND_USE_RPT_YY.getValue() + "년도 조달자금 사용보고를 팀장확인 하시겠습니까? ")) {
                return 1;
            } else {
                return false;
            }
        }
    }
};





/********************************************** 
 * 함수명   : fn_setUnqNm
 * 설명       : 고유명에 SRI 채권 구분값 추가하기
 ***********************************************/
scwin.fn_setUnqNm = function(row, v_SRI_BND_TP_CD) {
    if (row == "") {
        return;
    }
    var unq_nm = dts_List.getCellData(row, "UNQ_ISU_NM");
    var unq_enq_nm = dts_List.getCellData(row, "UNQ_ISU_ENG_NM");
    if (unq_nm.length > 16) {
        $c.win.alert("한글 고유명의 자릿수(최대 20)가 ESG채권 구분 명을 추가하면 넘어갑니다. 구분명 추가를 직접 수정하세요.");
        txb_UNQ_ISU_NM.setValue(unq_nm);
        txb_UNQ_ISU_NM.focus();
    } else {
        if (v_SRI_BND_TP_CD == "1") {
            txb_UNQ_ISU_NM.setValue(unq_nm + "(녹)");
        } else if (v_SRI_BND_TP_CD == "2") {
            txb_UNQ_ISU_NM.setValue(unq_nm + "(사)");
        } else if (v_SRI_BND_TP_CD == "3") {
            txb_UNQ_ISU_NM.setValue(unq_nm + "(지)");
        }
    }
    if (unq_enq_nm.length > 17) {
        $c.win.alert("영문 고유명의 자릿수(최대 20)가 ESG채권 구분 명을 추가하면 넘어갑니다. 구분명 추가를 직접 수정하세요.");
        txb_UNQ_ISU_ENG_NM.setValue(unq_enq_nm);
        txb_UNQ_ISU_ENG_NM.focus();
    } else {
        if (v_SRI_BND_TP_CD == "1") {
            txb_UNQ_ISU_ENG_NM.setValue(unq_enq_nm + "(G)");
        } else if (v_SRI_BND_TP_CD == "2") {
            txb_UNQ_ISU_ENG_NM.setValue(unq_enq_nm + "(S)");
        } else if (v_SRI_BND_TP_CD == "3") {
            txb_UNQ_ISU_ENG_NM.setValue(unq_enq_nm + "(T)");
        }
    }
};




