/********************************************** 
 * 함수명   : sri_detail
 * 설명       : SRI 채권 신청 파일 조회
 ***********************************************/
scwin.sri_detail = function(row) {
    //데이터를 우선 지우고 신청ID가 없으면 스탑
    dts_detail.removeAll();
    if (row == "") {
        return;
    }
    scwin.p_APPL_SEQ = dts_List.getCellData(row, "APPL_ISU_SEQ");
    scwin.p_SRI_BND_TP_CD = $c.stf.getObjectValue(cmb_SRI_BND_TP_CD);
    scwin.p_STD_CD = $c.stf.getObjectValue(txb_STD_CD);
    var param = "&{P}V_APPL_ISU_SEQ=" + scwin.p_APPL_SEQ;
    param += "&{P}V_STD_CD=" + dts_List.getCellData(row, "STD_CD");
    var dsNm = 'BNSSRI_APPL_FILE_LIST';
    var qryId = 'lds.stf.bnssri.select.fileList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_detail, dsNm, qryId, param);

    //한글금액표기
    $c.stf.setObjectValue(txb_AmtHan1, $c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'ISU_AMT')));
    $c.stf.setObjectValue(txb_AmtHan2, $c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'SUPLY_FND_USE_RPT_EXECUTE_AMT')));
    $c.stf.setObjectValue(txb_AmtHan3, $c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'UNUSED_AMT')));
    $c.stf.setObjectValue(txb_AmtHan4, $c.bns.fn_ChgAmtToHan(dts_List.getCellData(row, 'EXECUTE_AMT_SUM')));

    // 자금조달사용연도 기준으로 고유
    if (dts_List.getCellData(row, "SUPLY_FND_USE_RPT_YY") == "") {
        scwin.p_SUPLY_YY = "N";
        scwin.fn_sri_obj_show(true);
        scwin.fn_suply_obj_show(false);
        txb_UNQ_ISU_NM.setReadOnly(true);
        txb_UNQ_ISU_ENG_NM.setReadOnly(true);
    } else {
        scwin.p_SUPLY_YY = "Y";
        scwin.fn_sri_obj_show(false);
        scwin.fn_suply_obj_show(true);
    }
};



/********************************************** 
 * 함수명   : sri_SlbDetail
 * 설명       : SLB(지속가능연계채권) 상세정보 조회
 ***********************************************/
scwin.sri_SlbDetail = function() {
    //데이터를 우선 지우고 신청ID가 없으면 스탑
    dts_SlbDetail.removeAll();
    var row = dts_List.getRowPosition();
    scwin.p_APPL_SEQ = dts_List.getCellData(row, "APPL_ISU_SEQ");
    scwin.p_STD_CD = $c.stf.getObjectValue(txb_STD_CD);
    var param = "&{P}V_STD_CD=" + dts_List.getCellData(row, "STD_CD");
    param += "&{P}V_APPL_ISU_SEQ=" + scwin.p_APPL_SEQ;
    var dsNm = 'BNSSRI_APPL_SLB_DETAIL_LIST';
    var qryId = 'lds.stf.bnssri.select.slbDetailList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SlbDetail, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : ins_return
 * 설명       : 반송후 로직 
 ***********************************************/
scwin.ins_return = function(vRsn) {
    var url = "/bns/IsuChgEtc.do?method=updateSriBndReturnBtn";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "STD_CD=" + scwin.p_STD_CD;
    param += ", APPL_ISU_SEQ=" + scwin.p_APPL_SEQ;
    param += ", RET_RSN=" + vRsn;
    trs_return.Action = $c.lc.fn_encodeNSession(url);
    trs_return.KeyName = "toinb_dataid4";
    trs_return.KeyValue = "JSP(I:pInput=dts_detail)";
    trs_return.Parameters = param;
    trs_return.Post();
};


/********************************************** 
 * 함수명   : sri_register (AS-IS)
 * 설명       : SRI 채권구분 접수
 ***********************************************/
scwin.sri_register = function() {
    if (scwin.fn_formCheck() == false) {
        return;
    }
    if (scwin.p_SUPLY_YY != "") {
        var url = "/bns/IsuChgEtc.do?method=updateSriBndRegisterBtn";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        var param = "STD_CD=" + scwin.p_STD_CD;
        param += ", APPL_ISU_SEQ=" + scwin.p_APPL_SEQ;
        param += ", SRI_BND_TP_CD=" + scwin.p_SRI_BND_TP_CD;
        param += ", V_SUPLY_YY=" + scwin.p_SUPLY_YY;
        trs_save.Action = $c.lc.fn_encodeNSession(url);
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_detail)";
        trs_save.Parameters = param;
        trs_save.Post();
    } else {
        $c.win.alert("접수리스트의 상세 내용을 확인하세요. ");
    }
};



