/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    var dsNm = 'BNS_INST_INFO';
    var param = '&{P}V_INST_NM=';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);

    //공통콤보
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_TP_CD, 'SRI_BND_TP_CD'); //SRI채권구분
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_REF_RULE_TP_CD, 'SRI_BND_REF_RULE_TP_CD'); //SRI채권준거원칙
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_EXT_REVW_INST_CD, 'EXT_REVW_INST_CD'); //외부검토기관
