 *******************************************************************/
scwin.fn_PopReturn = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS21901", "/bnslistbzappl/ULDBNS21901.gfm", "반송처리", obj_left, obj_top, 480, 280, "window");
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        APPL_ISU_SEQ: dts_List.getCellData(dts_List.getRowPosition(), "APPL_ISU_SEQ"),
        ISUR_NM: dts_List.getCellData(dts_List.getRowPosition(), "COM_NM"),
        ISU_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

