scwin.btn_Acpt_onclick = function() {
    //체크된 것 카운팅
    var nTrueCnt = 0;
    var nFalseCnt = 0;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            nTrueCnt++;
            if (dts_List.getCellData(nRow, "STAT") != "미처리") {
                nFalseCnt++;
            }
        }
    }
    if (nTrueCnt == 0) {
        $c.win.alert("선택된 정보가 없습니다.");
        return false;
    }
    if (nFalseCnt > 0) {
        $c.win.alert("접수는 [미처리] 상태만 선택 할 수 있습니다.\n\n선택된 정보를 확인하세요.");
        return false;
    }
    scwin.sri_registerAll(nTrueCnt);
    //sri_register();	//asis

};
